from bisect import bisect_left
class Solution:
    def minInversions(self, words: list[str], target: list[int]) -> int:
        pos = [0] * len(target)
        for i, word_id in enumerate(target): pos[word_id] = i
        trie = [{'children': {}, 'word': None}]
        for i, word in enumerate(words):
            node = 0
            for ch in word:
                children = trie[node]['children']
                if ch not in children: children[ch] = len(trie); trie.append({'children': {}, 'word': None})
                node = children[ch]
            trie[node]['word'] = i
        ranks = [None] * len(trie); costs = [0] * len(trie)
        for node in range(len(trie) - 1, -1, -1):
            children = list(trie[node]['children'].values())
            groups = [(child, ranks[child]) for child in children]
            m = len(groups); pair = [[0] * m for _ in range(m)]
            for a in range(m):
                for b in range(m):
                    if a != b:
                        pair[a][b] = sum(bisect_left(groups[b][1], x) for x in groups[a][1])
            dp = {0: 0}
            for mask in range(1 << m):
                if mask not in dp: continue
                for b in range(m):
                    if not (mask >> b) & 1:
                        extra = costs[groups[b][0]] + sum(pair[a][b] for a in range(m) if (mask >> a) & 1)
                        nm = mask | (1 << b); dp[nm] = min(dp.get(nm, 10**30), dp[mask] + extra)
            terminal = trie[node]['word']
            terminal_cost = sum(x < pos[terminal] for child in children for x in ranks[child]) if terminal is not None else 0
            costs[node] = dp[(1 << m) - 1] + terminal_cost
            merged = [pos[terminal]] if terminal is not None else []
            for child in children: merged.extend(ranks[child])
            ranks[node] = sorted(merged)
        return costs[0]
